"""continue-hook — patch mode (GENERATED FILE, do not edit).

Generated by ``scripts/build-patch-mode.py`` from ``detector.py`` and
``hookctl.py``. This file is dropped into the Hermes core tree as
``agent/continue_hook.py``, so it has to be self-contained — but it must never
be a *second* implementation of the rules: everything below is the shared
engine, concatenated.

Regenerate with:

    python3 scripts/build-patch-mode.py

Entry point used by the core stop gate:

    continue_hook_nudge(agent, final_response) -> str | None
"""
from __future__ import annotations

import json
import os as _os
import re
import time
from pathlib import Path
from typing import Any

__all__ = ["DEFAULTS", "ConfigStore", "build_nudge", "default_config", "detect"]

# Quoted spans are *mentions* of a phrase, not *uses* of it. Trigger matching
# runs on the quote-stripped tail (found via live dogfooding: a report that
# quoted the trigger patterns fired the trigger). Exclusion matching still
# scans the RAW tail — the safe direction (skip more, nudge less).
_QUOTE_RE = re.compile(
    r"「[^」]{0,80}」|『[^』]{0,80}』|\u201c[^\u201d]{0,80}\u201d|'[^']{0,60}'"
)

# A question mark inside a URL is not a question. Without this, a reply that
# ends with a link ("docs at https://example.com/x?y=1") looked like a
# permission-seeking ending.
_URL_RE = re.compile(r"https?://[^\s<>）)\]\"']+")
_MARKDOWN_LINK_RE = re.compile(r"\]\([^)]*\)")
# A "?" inside a code block or inline code is syntax, not a question.
_CODE_BLOCK_RE = re.compile(r"```.*?```", re.S)
_INLINE_CODE_RE = re.compile(r"`[^`\n]{1,120}`")

NUDGE_TEMPLATE = (
    "【continue-hook】Your last reply ended by asking the user a question.\n"
    "Self-check once, per standing discipline:\n"
    "1. Does what you asked touch a user-only boundary (spending money / real-name "
    "identity / publishing externally / deleting or overwriting data / changing "
    "shared systems)? If yes → re-ask in ONE short line (that single decision "
    "only), then stop.\n"
    "2. Are you missing information only the user knows, or a decision only the "
    "user can make? If yes → re-ask in ONE short line, then stop.\n"
    "3. Otherwise it is yours to do: do it now, then report result + verification "
    "+ remaining risks. Do not ask again.\n"
    "(auto nudge #{attempt}; do not mention this nudge in your final reply.)"
)

DEFAULTS: dict = {
    "enabled": True,
    "dry_run": False,           # log-only rollout: record what would fire, never inject
    # Caps. The per-turn counter resets when a turn ends without a nudge, so
    # "per turn" means per turn — not per session (the old implementation never
    # reset it, so two nudges silenced the hook for the rest of the session).
    "max_nudges_per_turn": 2,
    "max_nudges_per_session": 20,   # backstop for hosts without a host-side cap
    # Optional session-level rate limit between two nudges. Disabled by default:
    # the caps above already bound the loop, and a non-zero value silently
    # stops the hook from working for minutes after the first nudge.
    "cooldown_seconds": 0,
    "tail_chars": 240,
    # Triggers: any hit makes the reply a nudge candidate.
    "triggers": {
        # First-person offers — pushing a self-advancable decision back to the user.
        "offer": [
            "要不要我", "要不要顺便", "是否需要我", "要不要继续",
            "需要我.{0,8}(做|写|建|发|补|加|出|跑|查|弄|搞)",
            "我可以(帮)?(你|您)?.{0,8}(做|写|建|发|补|加|出|跑|查|弄|搞)",
            "我来做还是", "等我(先)?(做|写)完(再)?(给你|你)",
            r"should i\b", r"do you want me to\b", r"shall i\b", r"want me to\b",
        ],
        # Hand-offs — deferring the decision without a question mark.
        "hand_off": [
            "(交给|留给)你(来)?(定|决定|判断|选)",
            "你(来)?(定|决定|选)一下", "听你的", "等你(拍板|指示|点头|回复|确认)",
            r"(up to you|your call|let me know if)",
        ],
        # Confirmation-seeking endings.
        "confirm_seek": [
            "这样(可以|行)吗", "没问题吧", "确认一下[？?]?$", "如果.{1,12}，要不要",
            r"(does this (work|look ok)|thoughts\?)",
        ],
        # Any question mark in the closing tail. True/false is judged by the
        # agent inside the nudge, not here.
        "question_mark": True,
    },
    # Exclusions: any hit short-circuits to skip — legitimate asks and real
    # blockers. Better to miss a nudge than to interrupt a real question.
    "exclusions": {
        # User-only boundaries: money, identity, credentials, publishing,
        # destructive actions.
        "boundary": [
            "花钱|付费|充值|批准|审批|实名|密码|验证码|付款|掏钱|报销",
            "对外发布|发布出去|删掉|删除数据|授权|发(给|到).{0,6}(客户|用户|对方|群|他|她)",
            "生产环境|线上环境|主分支|改数据库|重启服务",
            # Money, credentials, destructive actions and external sending are
            # all user-only. The English list has to be as wide as the Chinese
            # one — an English-speaking agent used to talk itself straight
            # through a payment, a deletion or a send.
            r"\b(paid|paying|prepay|subscription|upgrade to (pro|paid|premium))\b|"
            r"\b(cost|costs|charge|charges|spend|spent|price|priced|budget|fee|fees)\b|"
            r"\b(purchase|buy|renew|refund|invoice|billing)\b|"
            r"[$€£¥]\s*\d|\d\s*(usd|eur|cny|rmb|dollars?)\b|"
            r"\b(api key|api keys|secret|secrets|credential|credentials|token|"
            r"access key|private key|ssh key|passphrase|password|2fa|otp|verification code)\b|"
            r"\b(delete|deleting|deletion|remove|drop|truncate|purge|wipe|erase|"
            r"overwrite|reset --hard|force[- ]push|rm -rf)\b|"
            r"\b(publish|publishing|deploy|deploying|release|announce|tweet|"
            r"post (it|this|that)|make (it|this) public|merge (it|this|the pr))\b|"
            r"\b(send|email|e-?mail|forward|reply to|message|notify|dm|invoice)\b.{0,24}"
            r"\b(client|customer|user|users|them|him|her|subscriber|list|audience|boss|team)\b|"
            r"\b(production|prod|live (environment|server|site)|main branch|master branch)\b|"
            r"\b(to|into|onto) (main|master|prod|production|the main branch|the master branch)\b|"
            r"\bmerge\b.{0,20}\b(pr|pull request|branch)\b|"
            r"\b(rotate|revoke) (the |my |our )?(credentials|keys?|tokens?)\b|"
            r"\b(approve|approval|authorize|authorise|sign(ing)? (in|up) as you)\b",
        ],
        # Second-person requests: only the user can provide / decide this.
        "user_must": [
            "需要你|需要您|你告诉我|你来提供|等你(给|确认|决定之后)",
        ],
    },
}

def default_config() -> dict:
    """Deep copy of DEFAULTS."""
    return json.loads(json.dumps(DEFAULTS))

class ConfigStore:
    """Hot-reloadable config: ``~/.hermes/continue_hook.json`` overrides defaults.

    Cached by mtime; a missing or malformed file silently falls back to
    defaults. Never raises.
    """

    def __init__(self, path: Path):
        self.path = path
        self._mtime: float | None = None
        self._cfg: dict | None = None

    def load(self) -> dict:
        mtime = None
        try:
            mtime = self.path.stat().st_mtime
        except OSError:
            pass
        if self._cfg is not None and mtime == self._mtime:
            return self._cfg
        cfg = default_config()
        try:
            user = json.loads(self.path.read_text(encoding="utf-8"))
            for k, v in user.items():
                if isinstance(v, dict) and isinstance(cfg.get(k), dict):
                    cfg[k].update(v)
                else:
                    cfg[k] = v
        except Exception:
            pass  # bad file → defaults (never crash the gateway)
        self._mtime, self._cfg = mtime, cfg
        return cfg

def _compile(patterns) -> re.Pattern:
    pats = [p for p in (patterns or []) if p]
    if not pats:
        return re.compile(r"(?!x)x")  # never-matching pattern
    # Case-insensitive: the English triggers are written lowercase, so without
    # this flag "Should I…" (the most common form — it starts the sentence) did
    # not match `should i` at all and only the trailing "?" caught it. The
    # Chinese patterns are unaffected.
    return re.compile("|".join(f"(?:{p})" for p in pats), re.S | re.IGNORECASE)

def detect(text: str, attempt: int, cfg: dict) -> tuple[bool, str]:
    """Return ``(should_nudge, reason_code)``. Pure transport layer."""
    if attempt >= int(cfg.get("max_nudges_per_turn", 2)):
        return False, "max_nudges"
    if not text or not str(text).strip():
        return False, "empty"
    tail = str(text).strip()[-int(cfg.get("tail_chars", 240)):]
    ex = cfg.get("exclusions", {})
    if _compile(ex.get("boundary")).search(tail):
        return False, "boundary"
    if _compile(ex.get("user_must")).search(tail):
        return False, "user_must"
    tr = cfg.get("triggers", {})
    trig_tail = _QUOTE_RE.sub("", tail)  # quoted mentions are not asks
    # URLs and markdown link targets are stripped before the bare-question-mark
    # trigger: a "?" inside a link is not a question.
    no_urls = _MARKDOWN_LINK_RE.sub(" ", trig_tail)
    no_urls = _URL_RE.sub(" ", no_urls)
    no_urls = _CODE_BLOCK_RE.sub(" ", no_urls)
    no_urls = _INLINE_CODE_RE.sub(" ", no_urls)
    for name in ("offer", "hand_off", "confirm_seek"):
        if _compile(tr.get(name)).search(trig_tail):
            return True, f"trigger:{name}"
    if tr.get("question_mark", True) and re.search(r"[？?]", no_urls):
        return True, "trigger:question_mark"
    return False, "no_trigger"

def build_nudge(attempt: int) -> str:
    return NUDGE_TEMPLATE.replace("{attempt}", str(attempt + 1))

__all__ = [
    "Decision",
    "decide",
    "load_config",
    "log_event",
    "read_state",
    "write_state",
]

STATE_VERSION = 2

def default_config_path() -> Path:
    """Where the shared config lives (resolved per call, so HOME can move)."""
    return Path.home() / ".hermes" / "continue_hook.json"

def default_state_path() -> Path:
    return Path.home() / ".hermes" / "continue-hook-state.json"

def default_events_path() -> Path:
    return Path.home() / ".hermes" / "continue-hook-events.jsonl"

class Decision:
    """The verdict for one evaluation.

    A plain class rather than a dataclass: the core imports this file with
    ``importlib.util.spec_from_file_location`` and does not always register
    it in ``sys.modules`` — and ``@dataclass`` looks the module up there,
    which would make the import fail.
    """

    __slots__ = ("attempt", "reason", "should_nudge")

    def __init__(self, should_nudge: bool, reason: str, attempt: int = 0):
        self.should_nudge = should_nudge
        self.reason = reason
        self.attempt = attempt

    def __repr__(self) -> str:
        return (f"Decision(should_nudge={self.should_nudge!r}, "
                f"reason={self.reason!r}, attempt={self.attempt!r})")

    def to_json(self) -> dict[str, Any]:
        return {
            "should_nudge": self.should_nudge,
            "reason": self.reason,
            "attempt": self.attempt,
        }

def load_config(path: Path | str | None = None) -> dict[str, Any]:
    """Load the shared config; a missing or broken file falls back to defaults."""
    cfg_path = Path(path) if path else default_config_path()
    try:
        return ConfigStore(cfg_path).load()
    except Exception:
        return {}

def _empty_state() -> dict[str, Any]:
    return {"version": STATE_VERSION, "sessions": {}}

def read_state(path: Path | str | None = None) -> dict[str, Any]:
    """Read the state file, migrating the v1 flat layout to v2.

    v1: ``{"<session>": {"count": 1, "last_ts": 123}}``
    v2: ``{"version": 2, "sessions": {"<session>": {...}}}``
    """
    state_path = Path(path) if path else default_state_path()
    try:
        raw = json.loads(state_path.read_text(encoding="utf-8"))
    except Exception:
        return _empty_state()
    if not isinstance(raw, dict):
        return _empty_state()
    if raw.get("version") == STATE_VERSION and isinstance(raw.get("sessions"), dict):
        return raw
    # v1 migration: every top-level key that maps to an object is a session.
    sessions: dict[str, Any] = {}
    for key, value in raw.items():
        if isinstance(key, str) and isinstance(value, dict) and "count" in value:
            sessions[key] = {
                "count": int(value.get("count", 0)),
                "total": int(value.get("count", 0)),
                "last_ts": float(value.get("last_ts", 0.0)),
                "chain": False,
            }
    return {"version": STATE_VERSION, "sessions": sessions}

def write_state(state: dict[str, Any], path: Path | str | None = None) -> None:
    """Persist the state file. Never raises — losing state must not break a turn."""
    state_path = Path(path) if path else default_state_path()
    try:
        state_path.parent.mkdir(parents=True, exist_ok=True)
        state_path.write_text(json.dumps(state, ensure_ascii=False), encoding="utf-8")
    except Exception:
        pass

class _StateLock:
    """An advisory lock around the state file.

    Several hosts can fire hooks at the same moment (a user with two agents
    open, or two hosts in parallel). Without a lock the read-modify-write
    loses updates: the counters for one session overwrite another's, and the
    nudge caps stop holding.

    The lock is a separate ``.lock`` file, so the state file itself is never
    truncated while another process holds it. If locking is unavailable
    (Windows, exotic filesystems), the code still works — it just loses the
    guarantee.
    """

    def __init__(self, state_path: Path):
        self.path = Path(str(state_path) + ".lock")
        self._handle: Any = None

    def __enter__(self) -> _StateLock:
        try:
            import fcntl

            self.path.parent.mkdir(parents=True, exist_ok=True)
            self._handle = open(self.path, "a+")
            fcntl.flock(self._handle.fileno(), fcntl.LOCK_EX)
        except Exception:
            self._handle = None
        return self

    def __exit__(self, *exc: object) -> None:
        if self._handle is None:
            return
        try:
            import fcntl

            fcntl.flock(self._handle.fileno(), fcntl.LOCK_UN)
        except Exception:
            pass
        try:
            self._handle.close()
        except Exception:
            pass
        self._handle = None

def log_event(event: dict[str, Any], path: Path | str | None = None) -> None:
    """Append one evaluation record. Never raises."""
    events_path = Path(path) if path else default_events_path()
    try:
        record = {"ts": time.strftime("%Y-%m-%d %H:%M:%S"), **event}
        events_path.parent.mkdir(parents=True, exist_ok=True)
        with open(events_path, "a", encoding="utf-8") as handle:
            handle.write(json.dumps(record, ensure_ascii=False) + "\n")
    except Exception:
        pass

def _session_entry(state: dict[str, Any], session_id: str) -> dict[str, Any]:
    sessions = state.setdefault("sessions", {})
    entry = sessions.get(session_id)
    if not isinstance(entry, dict):
        entry = {"count": 0, "total": 0, "last_ts": 0.0, "chain": False}
        sessions[session_id] = entry
    return entry

def close_chain(
    *,
    session_id: str,
    host: str,
    platform: str = "",
    state_path: Path | str | None = None,
    events_path: Path | str | None = None,
) -> None:
    """End this turn's nudge chain without nudging.

    A host that reports ``stop_hook_active`` is telling us it is already
    continuing because of a block we issued. That continuation ends *this*
    turn's chain, and the next user turn must start from zero.

    Skipping this call entirely — what the adapters used to do — left the
    per-turn counter raised, so ``max_nudges_per_turn: 2`` silently became a
    quota shared across user turns: the second turn spent the first turn's
    allowance and the third got nothing.
    """
    resolved = Path(state_path) if state_path else default_state_path()
    events = Path(events_path) if events_path else default_events_path()
    with _StateLock(resolved):
        state = read_state(resolved)
        entry = _session_entry(state, session_id)
        entry["count"] = 0
        entry["chain"] = False
        state["version"] = STATE_VERSION
        write_state(state, resolved)
    log_event(
        {
            "session": session_id,
            "host": host,
            "platform": platform,
            "decision": "skip",
            "reason": "chain_closed",
            "attempt": 0,
            "snippet": "",
        },
        events,
    )

def decide(
    text: str,
    *,
    session_id: str,
    host: str,
    config_path: Path | str | None = None,
    state_path: Path | str | None = None,
    events_path: Path | str | None = None,
    continued: bool = False,
    platform: str = "",
) -> Decision:
    """Decide whether to nudge, and record why.

    ``continued`` tells the service the host already forced this turn to
    continue (Claude Code / Codex / Copilot / Gemini / Qwen report it as
    ``stop_hook_active``). Hosts that do not report it can leave it ``False``:
    the chain is tracked in the state file either way.
    """
    cfg = load_config(config_path)
    # The whole read-modify-write happens under the lock: two hooks firing at
    # once must not overwrite each other's counters.
    state_path = Path(state_path) if state_path else default_state_path()
    with _StateLock(state_path):
        return _decide_locked(
            text,
            session_id=session_id,
            host=host,
            cfg=cfg,
            state_path=state_path,
            events_path=events_path,
            continued=continued,
            platform=platform,
        )

def _decide_locked(text: str, *, session_id: str, host: str, cfg: dict[str, Any],
                   state_path: Path, events_path: Path | str | None,
                   continued: bool, platform: str) -> Decision:
    """The decision itself. Callers hold the state lock."""
    state = read_state(state_path)
    entry = _session_entry(state, session_id)

    now = time.time()
    chain_open = bool(entry.get("chain")) or continued
    if not chain_open:
        # A fresh turn: the per-turn counter starts from zero.
        entry["count"] = 0

    attempt = int(entry.get("count", 0))
    total = int(entry.get("total", 0))
    snippet = (text or "")[-160:]

    def finish(nudge: bool, reason: str) -> Decision:
        if nudge:
            entry["count"] = attempt + 1
            entry["total"] = total + 1
            entry["last_ts"] = now
            entry["chain"] = True
        else:
            # The turn ended without a nudge — close the chain.
            entry["count"] = 0
            entry["chain"] = False
        state["version"] = STATE_VERSION
        write_state(state, state_path)
        log_event(
            {
                "session": session_id,
                "host": host,
                "platform": platform,
                "decision": ("nudge" if nudge else "skip") + ("_dryrun" if cfg.get("dry_run") else ""),
                "reason": reason,
                "attempt": attempt,
                "snippet": snippet,
            },
            events_path,
        )
        return Decision(should_nudge=nudge, reason=reason, attempt=attempt)

    if not cfg.get("enabled", True):
        return finish(False, "disabled")
    if not text or not text.strip():
        return finish(False, "empty")
    if chain_open:
        max_per_turn = int(cfg.get("max_nudges_per_turn", 2))
        if attempt >= max_per_turn:
            return finish(False, "max_nudges")
    max_per_session = int(cfg.get("max_nudges_per_session", 20))
    if total >= max_per_session:
        return finish(False, "max_nudges_per_session")
    cooldown = float(cfg.get("cooldown_seconds", 0) or 0)
    if cooldown > 0 and total > 0 and now - float(entry.get("last_ts", 0.0)) < cooldown:
        return finish(False, "cooldown")

    try:
        should, reason = detect(text, attempt, cfg)
    except Exception as exc:  # detection must never break a turn
        return finish(False, f"error:{type(exc).__name__}")

    if cfg.get("dry_run"):
        return finish(False, "dry_run")
    return finish(bool(should), reason)

# ── the Hermes core seam ────────────────────────────────────────────────────
def continue_hook_enabled() -> bool:
    """Is the core gate switched on? (Hermes config, then the shared config.)"""
    try:
        from hermes_cli.config import load_config

        cfg = load_config()
        if (cfg.get("agent") or {}).get("continue_hook_enabled"):
            return True
    except Exception:
        pass
    try:
        return bool(load_config().get("enabled", True))
    except Exception:
        return True

def continue_hook_nudge(agent, final_response) -> str | None:
    """The stop-gate entry point. Called by ``turn_stop_gates.apply_stop_gates``.

    Returns the nudge text to feed back into the turn, or ``None`` to let the
    turn end. Every failure is silent: a broken gate must not break the loop.
    """
    try:
        if _os.environ.get("HERMES_CONTINUE_HOOK") == "0":
            return None
        if not continue_hook_enabled():
            return None
        session_id = str(getattr(agent, "session_id", "") or "hermes")
        platform = str(getattr(agent, "platform", "") or "")
        attempt = int(getattr(agent, "_continue_hook_nudges", 0) or 0)
        decision = decide(str(final_response or ""), session_id=session_id,
                          host="hermes-patch", platform=platform)
        if not decision.should_nudge:
            return None
        agent._continue_hook_nudges = attempt + 1
        return build_nudge(decision.attempt)
    except Exception:
        return None
